for thr in [55, 60, 65]:
    cand = (inside < thr) & pm
    lab, blobs = label_blobs(cand, min_area=3)
    print("thr", thr, "cand px", cand.sum(), "nblobs", len(blobs))
    for b in blobs[:8]:
        print("  ", b['id'], b['area'], round(b['cy'],1), round(b['cx'],1), round(b['elongation'],2))

void_mask = np.zeros_like(pm)
for b in blobs:
    if b['elongation'] < 2.5 and b['area'] >= 8:
        void_mask[lab == b['id']] = True
show(overlay(img, [pm, void_mask]), "part(red)+voids(green)")
print("void px", void_mask.sum())

voids=[]; cracks=[]
for b in blobs:
    if b['area']<8: continue
    if b['elongation']>3:
        cracks.append(b)
    else:
        voids.append(b)
print("VOIDS:")
for b in voids: print(b)
print("CRACKS:")
for b in cracks: print(b)
void_px=sum(b['area'] for b in voids)
print("void px:", void_px, "part px:", pm.sum(), "ratio:", 100*void_px/pm.sum())

